{"CommandLine":"powershell -Command "
`$targets = @(
    'C:\AI-BS',
    'C:\AI-BS\ComfyUI',
    'C:\AI-BS\node_modules',
    'C:\AI-BS\frontend\node_modules',
    'C:\Users\footb\.ollama',
    'C:\Users\footb\.cache',
    'C:\Users\footb\AppData\Local\Docker',
    'C:\Users\footb\AppData\Local\Packages'
)
foreach (`$t in `$targets) {
    if (Test-Path `$t) {
        `$bytes = (Get-ChildItem `$t -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        [PSCustomObject]@{ Target = `$t; SizeGB = [math]::Round(`$bytes / 1GB, 2) }
    }
}
"","Cwd":"C:\AI-BS","WaitMsBeforeAsync":15000,"toolAction":"Check specific known heavy directories","toolSummary":"Inspect heavy directories"}
